namespace ResearchAgent;

/// <summary>
/// Simple in-memory note-taking service for the research agent.
/// </summary>
public sealed class NoteService
{
    private readonly List<Note> _notes = [];
    private int _nextId = 1;

    public Note AddNote(string title, string content)
    {
        var note = new Note(_nextId++, title, content, DateTime.UtcNow);
        _notes.Add(note);
        return note;
    }

    public IReadOnlyList<Note> GetAllNotes() => _notes.AsReadOnly();

    public Note? GetNote(int id) => _notes.Find(n => n.Id == id);
}

public sealed record Note(int Id, string Title, string Content, DateTime CreatedAt);

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly NoteService _noteService;
    private static readonly HttpClient HttpClient = new();

    public ResearchTools(NoteService noteService)
    {
        _noteService = noteService;
    }

    public IList<AITool> GetTools() =>
    [
        AIFunctionFactory.Create(SearchWebAsync),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ];

    [Description("Search the web for information on a given query. Returns a list of search results with titles, URLs, and snippets.")]
    private async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        try
        {
            // Uses DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetFromJsonAsync<JsonElement>(url);
            var results = new List<string>();

            // Extract abstract if available
            var abstractText = response.GetProperty("Abstract").GetString();
            var abstractSource = response.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var topicText = text.GetString();
                        if (!string.IsNullOrEmpty(topicText))
                        {
                            var topicUrl = topic.TryGetProperty("FirstURL", out var u)
                                ? u.GetString() : "";
                            results.Add($"- {topicText} ({topicUrl})");
                        }
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing the search.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to record important findings during research. Use this to save key facts and insights.")]
    private string TakeNote(
        [Description("A short title for the note")] string title,
        [Description("The content/body of the note with key findings")] string content)
    {
        Console.WriteLine($"  [Tool] Taking note: \"{title}\"");
        var note = _noteService.AddNote(title, content);
        return $"Note #{note.Id} saved: \"{note.Title}\"";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    private string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving notes");
        var notes = _noteService.GetAllNotes();
        if (notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return string.Join("\n\n", notes.Select(n =>
            $"Note #{n.Id} - {n.Title} ({n.CreatedAt:HH:mm:ss})\n{n.Content}"));
    }
}

